//! Native process boundary for the jscodeshift command-line interface.
//!
//! Transforms are JavaScript programs and expose the historic jscodeshift
//! JavaScript API.  The host is therefore deliberately a tiny compatibility
//! boundary; argument bytes, standard streams, current directory, environment,
//! exit status, and signal status are passed through without interpretation.

use std::env;
use std::path::PathBuf;
use std::process::{Command, ExitCode};

fn host_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("rust crate must live under the package root")
        .join("bridge")
        .join("transform-host.js")
}

fn main() -> ExitCode {
    let status = match Command::new(env::var_os("JSCODESHIFT_NODE").unwrap_or_else(|| "node".into()))
        .arg(host_path())
        .args(env::args_os().skip(1))
        .status()
