        Ok(status) => status,
        Err(error) => {
            eprintln!("jscodeshift: unable to start JavaScript transform host: {error}");
            return ExitCode::from(1);
        }
    };

    ExitCode::from(status.code().unwrap_or(1) as u8)
}
